let deviceType = arguments[0];
var host = $System.host; //IP和端口为计算工程部署在运维中心的IP和端口
var api = 'getDeviceTypeTag'; //计算工程的请求式脚本名称，注意是请求式脚本名称，而非函数名称
var type = 'post';
let guid = $Function.generateGuid();
var data = {
    "InParam": {
        "deviceType": deviceType
    },
    "RequestType": "normal",
    "RequestID": guid
};
//调用方式
let options = {
    offset: 20,
    duration: 2000,
    width: '150px',
    height: '40px',
    center: true,
    showClose: false
}
var postType = 'JSON';
httpRequestExec(host, api, type, data, postType, function(res) {
    if (res.code === 0) {
        Select2.$vm.selectValue = res.data[0].value;
        Select2.SetData(res.data);
