// 生成 GUID
function generateGuid() {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        var r = Math.random() * 16 | 0,
            v = c === 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
}
// 获取当前时间
let time = datetimepicker1.GetCurrentValue();
// 获取设备名称
let deviceName = Select2.$vm.selectValue;

// 设置图表选项
let option = {
    xAxis: [{
        data: []
    }],
    yAxis: [{
        // 设置 y 轴最小值
        min: function(value) {
            return Math.floor(value.min * 0.9)
        },
        // 设置 y 轴最大值
        max: function(value) {
            return Math.ceil(value.max * 1.1)
        }
    }],
    series: [{
        data: []
    }]
};

// 调用方式选项
let options = {
    offset: 20,
    duration: 2000,
    width: '150px',
    height: '40px',
    center: true,
    showClose: false
}

// 设置表格数据
function setTable() {
    // 如果时间为字符串，则返回
    if (typeof time === 'string') {
        return
    }
    // 如果设备名称为空，则返回
    if (deviceName === '') {
        return
    }
    // 获取主机地址
    var host = 'http://192.168.1.101:10002'; //IP和端口为计算工程部署在运维中心的IP和端口
    // 设置API名称
    var api = 'Trend'; //计算工程的请求式脚本名称，注意是请求式脚本名称，而非函数名称
    var type = 'post';
    // 生成唯一标识符
    let guid = generateGuid();
    var data = {
        // 设置请求参数
        "InParam": {
            "deviceName": deviceName,
            "startTime": time[0],
            "endTime": time[1]
        },
        "RequestType": "normal",
        "RequestID": guid
    };
    var postType = 'JSON';
    // 显示加载层
    layer.load(0, {
        shade: [0.6, '#000']
    });
    // 发起HTTP请求
    httpRequestExec(host, api, type, data, postType, function(res) {
        // 关闭所有加载层
        layer.closeAll('loading');
        if (res.code === 0) {
            // 设置表格数据
            Table1.SetData(res.data.tableData)
            // 设置图表数据
            for (let i in res.data.echartsData) {
                switch (i) {
                    case '电压':
                        option.series[0].data = res.data.echartsData[i].DataValue
                        option.xAxis[0].data = res.data.echartsData[i].TimeStamp
                        CustomCharts2.$Children.echart.setOption(option, false);
                        CustomCharts2.$Children.echart.setOption(option);
                        break;
                    case '电流':
                        option.series[0].data = res.data.echartsData[i].DataValue
                        option.xAxis[0].data = res.data.echartsData[i].TimeStamp
                        CustomCharts3.$Children.echart.setOption(option, false);
                        CustomCharts3.$Children.echart.setOption(option);
                        break;
                    case '功率':
                        option.series[0].data = res.data.echartsData[i].DataValue
                        option.xAxis[0].data = res.data.echartsData[i].TimeStamp
                        CustomCharts1.$Children.echart.setOption(option, false);
                        CustomCharts1.$Children.echart.setOption(option);
                        break;
                }
            }
            // 显示查询成功消息提示
            options.message = '查询成功';
            options.type = 'success';
            options.color = '#155724';
            options.backgroundColor = '#d4edda';
            ShowMessage(options) // 展示消息提示弹窗
        } else {
            // 显示查询失败消息提示
            options.message = '查询失败';
            options.type = 'error';
            options.color = '#856404';
            options.backgroundColor = '#fff3cd';
            ShowMessage(options) // 展示消息提示弹窗
        }
    }, $System.timeout);
}

// 调用设置表格函数
setTable();

