// 获取表格数据
let data = Table1.GetData();
// 获取表格列信息
let ColumnsArray = Table1.GetColumns();
// 存储报表数据的数组
let reportDataArr = [];
// 提取列的属性和标签
let props = ColumnsArray.map(item => item.prop);
let labels = ColumnsArray.map(item => item.label);
// 遍历表格数据
for (let i in data) {
    let reportRow = {};
    // 构建报表行数据
    for (let j = 0; j < props.length; j++) {
        reportRow[labels[j]] = data[i][props[j]];
    }
    reportDataArr.push(reportRow); // 将行数据添加到报表数据数组中
}

// 获取当前时间
function getTime() {
    const now = new Date();
    const year = now.getFullYear().toString();
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const day = now.getDate().toString().padStart(2, '0');
    const hour = now.getHours().toString().padStart(2, '0');
    const minute = now.getMinutes().toString().padStart(2, '0');
    const second = now.getSeconds().toString().padStart(2, '0');
    const result = year + month + day + hour + minute + second;
    return result;
}
let time = getTime(); // 获取时间戳

// 导出表格数据到 Excel
ExportToExcel(reportDataArr, '趋势曲线表格导出' + time);

